-- ═════════════════════════════════════════════════════════════════════════════════════════════
-- Hand-written part (Prisma cannot express it): RLS for system rows, partial / NULLS NOT DISTINCT unique indexes, CHECKs,
-- status machines, frozen content, append-only logs.
-- Constraint, index, function, policy and trigger names below are part of the migration contract
-- (tests/db/phase7-schema.test.ts). The generic guards leadro_append_only (Phase 2), leadro_immutable_columns,
-- leadro_status_transitions and leadro_no_delete (Phase 4) are reused as they are.
-- The new ApprovalSubjectType values are not used by this migration, so it runs inside one transaction.
-- ═════════════════════════════════════════════════════════════════════════════════════════════

-- ───────────── Row-level security ─────────────
-- Same fail-closed DO-block as Phase 1-6: every table with a "tenantId" column (the 11 new ones included) is ENABLEd + FORCEd and
-- gets the tenant_isolation policy. A row whose "tenantId" is NULL (a system job or system schedule) never equals the setting,
-- so a tenant context never sees it, and no context at all sees nothing. Re-running it is idempotent.
DO $$
DECLARE
  t record;
BEGIN
  FOR t IN
    SELECT c.table_name
    FROM information_schema.columns c
    JOIN information_schema.tables tb
      ON tb.table_schema = c.table_schema AND tb.table_name = c.table_name AND tb.table_type = 'BASE TABLE'
    WHERE c.table_schema = 'public' AND c.column_name = 'tenantId'
  LOOP
    EXECUTE format('ALTER TABLE %I ENABLE ROW LEVEL SECURITY', t.table_name);
    EXECUTE format('ALTER TABLE %I FORCE ROW LEVEL SECURITY', t.table_name);
    EXECUTE format('DROP POLICY IF EXISTS tenant_isolation ON %I', t.table_name);
    EXECUTE format(
      'CREATE POLICY tenant_isolation ON %I USING ("tenantId" = (SELECT NULLIF(current_setting(''app.tenant_id'', true), ''''))) WITH CHECK ("tenantId" = (SELECT NULLIF(current_setting(''app.tenant_id'', true), '''')))',
      t.table_name
    );
  END LOOP;
END
$$;

-- The queue worker path (Task 2: the worker claims jobs of every tenant, the scheduler reads every definition, the outbox
-- dispatcher reads every undelivered event) runs in a transaction with `app.queue_worker = 'on'` (set transaction-locally, like
-- app.tenant_id) and sees every row of these three tables, system rows included. They hold ids only (CHECKs below cap the
-- payload size), never business data; the handler itself then runs inside withTenant(job.tenantId). Policies are permissive, so
-- a row is visible when tenant_isolation OR queue_worker allows it. No other table has this policy.
CREATE POLICY queue_worker ON "BackgroundJob"
  USING ((SELECT current_setting('app.queue_worker', true)) = 'on')
  WITH CHECK ((SELECT current_setting('app.queue_worker', true)) = 'on');
CREATE POLICY queue_worker ON "ScheduledJobDefinition"
  USING ((SELECT current_setting('app.queue_worker', true)) = 'on')
  WITH CHECK ((SELECT current_setting('app.queue_worker', true)) = 'on');
CREATE POLICY queue_worker ON "DomainEventOutbox"
  USING ((SELECT current_setting('app.queue_worker', true)) = 'on')
  WITH CHECK ((SELECT current_setting('app.queue_worker', true)) = 'on');

-- ───────────── Shared shape helpers ─────────────
-- A stable machine code (error, status, rejection, handling verdict): snake_case, never a message.
CREATE OR REPLACE FUNCTION leadro_is_code(v text) RETURNS boolean
LANGUAGE sql IMMUTABLE AS $$
  SELECT v ~ '^[a-z][a-z0-9_]{0,62}$'
$$;

-- A dotted catalog key such as "job_outcome.reported" or "follow_ups.due_sweep" (2-4 snake_case parts).
CREATE OR REPLACE FUNCTION leadro_is_dotted_key(v text) RETURNS boolean
LANGUAGE sql IMMUTABLE AS $$
  SELECT v ~ '^[a-z][a-z0-9_]{0,62}(\.[a-z][a-z0-9_]{0,62}){1,3}$'
$$;

-- A small JSON object (ids and scalars): an object of at most max_bytes as text.
CREATE OR REPLACE FUNCTION leadro_is_small_json_object(j jsonb, max_bytes int) RETURNS boolean
LANGUAGE sql IMMUTABLE AS $$
  SELECT j IS NOT NULL AND jsonb_typeof(j) = 'object' AND octet_length(j::text) <= max_bytes
$$;

-- A JSON array of min_len..max_len objects.
CREATE OR REPLACE FUNCTION leadro_is_json_object_array(j jsonb, min_len int, max_len int) RETURNS boolean
LANGUAGE sql IMMUTABLE AS $$
  SELECT CASE
    WHEN j IS NULL OR jsonb_typeof(j) <> 'array' THEN false
    ELSE jsonb_array_length(j) BETWEEN min_len AND max_len
      AND NOT EXISTS (SELECT 1 FROM jsonb_array_elements(j) AS e WHERE jsonb_typeof(e) <> 'object')
  END
$$;

-- Secrets are never stored (spec 18.1): a JSON document with a key that looks like a secret (at any depth) is refused, so a
-- token pasted into a configuration object fails loudly. Credentials live behind Integration.credentialsRef. A harmless key that
-- merely contains one of these words (e.g. "tokenizedField") is refused too: rename it.
CREATE OR REPLACE FUNCTION leadro_json_has_secret_key(j jsonb) RETURNS boolean
LANGUAGE sql IMMUTABLE AS $$
  SELECT j IS NOT NULL AND jsonb_path_exists(
    j,
    'lax $.** ? (@.type() == "object").keyvalue() ? (@.key like_regex "(secret|passw|token|api_?key|private_?key|credential|bearer|signature)" flag "i")'
  )
$$;

-- Columns named in the trigger arguments may go from NULL to a value once; after that they never change.
CREATE OR REPLACE FUNCTION leadro_set_once_columns() RETURNS trigger
LANGUAGE plpgsql AS $$
DECLARE
  i int;
BEGIN
  FOR i IN 0 .. TG_NARGS - 1 LOOP
    IF to_jsonb(OLD) -> TG_ARGV[i] <> 'null'::jsonb
       AND to_jsonb(OLD) -> TG_ARGV[i] IS DISTINCT FROM to_jsonb(NEW) -> TG_ARGV[i] THEN
      RAISE EXCEPTION '%.% is set once and never changed', TG_TABLE_NAME, TG_ARGV[i]
        USING ERRCODE = 'restrict_violation';
    END IF;
  END LOOP;
  RETURN NEW;
END
$$;

-- ───────────── Background jobs ─────────────
ALTER TABLE "BackgroundJob" ADD CONSTRAINT background_job_type_format CHECK (leadro_is_dotted_key("type"));
ALTER TABLE "BackgroundJob" ADD CONSTRAINT background_job_payload_small CHECK (leadro_is_small_json_object("payload", 4096));
ALTER TABLE "BackgroundJob" ADD CONSTRAINT background_job_priority_range CHECK ("priority" BETWEEN 0 AND 1000);
ALTER TABLE "BackgroundJob" ADD CONSTRAINT background_job_attempts
  CHECK ("maxAttempts" BETWEEN 1 AND 25 AND "attempts" BETWEEN 0 AND "maxAttempts");
-- Exactly the RUNNING job holds a lock (who and since when).
ALTER TABLE "BackgroundJob" ADD CONSTRAINT background_job_lock
  CHECK (("status" = 'RUNNING') = ("lockedBy" IS NOT NULL) AND ("lockedBy" IS NULL) = ("lockedAt" IS NULL)
    AND ("lockedBy" IS NULL OR length(btrim("lockedBy")) BETWEEN 1 AND 200));
-- A failure is a stable code with its time; FAILED and DEAD always say why.
ALTER TABLE "BackgroundJob" ADD CONSTRAINT background_job_error
  CHECK (("lastErrorCode" IS NULL) = ("lastErrorAt" IS NULL)
    AND ("lastErrorCode" IS NULL OR leadro_is_code("lastErrorCode"))
    AND ("status" NOT IN ('FAILED', 'DEAD') OR "lastErrorCode" IS NOT NULL));
ALTER TABLE "BackgroundJob" ADD CONSTRAINT background_job_completed CHECK (("status" = 'SUCCEEDED') = ("completedAt" IS NOT NULL));
ALTER TABLE "BackgroundJob" ADD CONSTRAINT background_job_idempotency_key_length
  CHECK ("idempotencyKey" IS NULL OR length("idempotencyKey") BETWEEN 1 AND 200);
ALTER TABLE "BackgroundJob" ADD CONSTRAINT background_job_schedule
  CHECK (("scheduleKey" IS NULL) = ("scheduleWindow" IS NULL)
    AND ("scheduleKey" IS NULL OR (leadro_is_dotted_key("scheduleKey") OR leadro_is_code("scheduleKey"))));
-- Idempotent enqueue: one job per (tenant, key); system jobs (NULL tenant) share one namespace.
CREATE UNIQUE INDEX background_job_idempotency
  ON "BackgroundJob" ("tenantId", "idempotencyKey") NULLS NOT DISTINCT WHERE "idempotencyKey" IS NOT NULL;
-- The claim query (FOR UPDATE SKIP LOCKED) reads claimable jobs in priority, then due-time order.
CREATE INDEX background_job_claimable ON "BackgroundJob" ("priority", "runAt") WHERE "status" IN ('QUEUED', 'FAILED');
-- Stale-lock detection reads running jobs by heartbeat.
CREATE INDEX background_job_running ON "BackgroundJob" ("heartbeatAt") WHERE "status" = 'RUNNING';
-- QUEUED -> RUNNING -> SUCCEEDED | FAILED (retry later) | DEAD (dead letter); RUNNING -> QUEUED releases a claim (shutdown);
-- FAILED -> RUNNING is the retry; FAILED -> DEAD gives up; DEAD -> QUEUED is the admin retry. SUCCEEDED is final.
CREATE TRIGGER background_job_status
  BEFORE UPDATE ON "BackgroundJob"
  FOR EACH ROW EXECUTE FUNCTION leadro_status_transitions(
    'QUEUED>RUNNING', 'RUNNING>SUCCEEDED', 'RUNNING>FAILED', 'RUNNING>DEAD', 'RUNNING>QUEUED', 'FAILED>RUNNING', 'FAILED>DEAD',
    'DEAD>QUEUED');
CREATE TRIGGER background_job_immutable
  BEFORE UPDATE ON "BackgroundJob"
  FOR EACH ROW EXECUTE FUNCTION leadro_immutable_columns(
    'id', 'tenantId', 'type', 'payload', 'idempotencyKey', 'scheduleKey', 'scheduleWindow', 'createdAt');
-- Only finished (SUCCEEDED) jobs may be deleted, by a retention sweep; failed and dead jobs stay for inspection.
CREATE OR REPLACE FUNCTION leadro_background_job_delete_guard() RETURNS trigger
LANGUAGE plpgsql AS $$
BEGIN
  IF OLD."status" <> 'SUCCEEDED' THEN
    RAISE EXCEPTION 'only SUCCEEDED background jobs may be deleted (job % is %)', OLD."id", OLD."status"
      USING ERRCODE = 'restrict_violation';
  END IF;
  RETURN OLD;
END
$$;
CREATE TRIGGER background_job_delete_guard
  BEFORE DELETE ON "BackgroundJob" FOR EACH ROW EXECUTE FUNCTION leadro_background_job_delete_guard();

-- ───────────── Scheduled job definitions ─────────────
ALTER TABLE "ScheduledJobDefinition" ADD CONSTRAINT scheduled_job_definition_key_format
  CHECK (leadro_is_dotted_key("key") OR leadro_is_code("key"));
ALTER TABLE "ScheduledJobDefinition" ADD CONSTRAINT scheduled_job_definition_job_type_format CHECK (leadro_is_dotted_key("jobType"));
-- Five cron fields (minute hour day-of-month month day-of-week); the scheduler parses and validates the values.
ALTER TABLE "ScheduledJobDefinition" ADD CONSTRAINT scheduled_job_definition_cron_shape
  CHECK ("cron" ~ '^[0-9A-Za-z*/,?-]+( [0-9A-Za-z*/,?-]+){4}$');
ALTER TABLE "ScheduledJobDefinition" ADD CONSTRAINT scheduled_job_definition_time_zone_shape
  CHECK ("timeZone" ~ '^[A-Za-z][A-Za-z0-9_+-]*(/[A-Za-z0-9_+-]+){0,2}$');
ALTER TABLE "ScheduledJobDefinition" ADD CONSTRAINT scheduled_job_definition_last_run
  CHECK (("lastRunAt" IS NULL) = ("lastWindow" IS NULL));
-- One definition per (tenant, key); system definitions (NULL tenant) share one namespace.
-- (Written as a partial index so that `prisma migrate diff` leaves it alone; the predicate is always true.)
CREATE UNIQUE INDEX scheduled_job_definition_key ON "ScheduledJobDefinition" ("tenantId", "key") NULLS NOT DISTINCT WHERE "key" IS NOT NULL;
CREATE TRIGGER scheduled_job_definition_immutable
  BEFORE UPDATE ON "ScheduledJobDefinition"
  FOR EACH ROW EXECUTE FUNCTION leadro_immutable_columns('id', 'tenantId', 'key', 'createdAt');
-- Disabled, never deleted (the scheduler's history of windows refers to the key).
CREATE TRIGGER scheduled_job_definition_no_delete
  BEFORE DELETE ON "ScheduledJobDefinition" FOR EACH ROW EXECUTE FUNCTION leadro_no_delete();

-- ───────────── Domain event outbox ─────────────
ALTER TABLE "DomainEventOutbox" ADD CONSTRAINT domain_event_type_format CHECK (leadro_is_dotted_key("eventType"));
ALTER TABLE "DomainEventOutbox" ADD CONSTRAINT domain_event_aggregate
  CHECK ("aggregateType" ~ '^[A-Z][A-Za-z0-9]{0,62}$' AND length(btrim("aggregateId")) BETWEEN 1 AND 64);
ALTER TABLE "DomainEventOutbox" ADD CONSTRAINT domain_event_payload_small CHECK (leadro_is_small_json_object("payload", 8192));
-- The causation chain is a list of event ids, root first, capped (the engine's depth limit is lower; this is the hard stop).
ALTER TABLE "DomainEventOutbox" ADD CONSTRAINT domain_event_causation_chain
  CHECK (cardinality("causationChain") <= 16 AND array_position("causationChain", NULL) IS NULL);
-- An event emitted by an automation action carries its cause: the rule version and at least one earlier event.
ALTER TABLE "DomainEventOutbox" ADD CONSTRAINT domain_event_rule_cause
  CHECK ("causedByRuleVersionId" IS NULL OR cardinality("causationChain") >= 1);
ALTER TABLE "DomainEventOutbox" ADD CONSTRAINT domain_event_actor
  CHECK (NOT ("actorUserId" IS NOT NULL AND "systemActor" IS NOT NULL)
    AND ("systemActor" IS NULL OR "systemActor" ~ '^system:[a-z][a-z0-9_.-]{0,62}$'));
-- The dispatcher reads undelivered events in order.
CREATE INDEX domain_event_undispatched ON "DomainEventOutbox" ("occurredAt") WHERE "dispatchedAt" IS NULL;
-- An event is a fact: only its delivery time is written later, once.
CREATE TRIGGER domain_event_immutable
  BEFORE UPDATE ON "DomainEventOutbox"
  FOR EACH ROW EXECUTE FUNCTION leadro_immutable_columns(
    'id', 'tenantId', 'eventType', 'aggregateType', 'aggregateId', 'payload', 'causationChain', 'causedByRuleVersionId',
    'correlationId', 'actorUserId', 'systemActor', 'occurredAt');
CREATE TRIGGER domain_event_dispatched_once
  BEFORE UPDATE ON "DomainEventOutbox" FOR EACH ROW EXECUTE FUNCTION leadro_set_once_columns('dispatchedAt');
CREATE TRIGGER domain_event_no_delete BEFORE DELETE ON "DomainEventOutbox" FOR EACH ROW EXECUTE FUNCTION leadro_no_delete();

-- ───────────── Automation rules ─────────────
ALTER TABLE "AutomationRule" ADD CONSTRAINT automation_rule_key_format CHECK (leadro_is_code("key"));
ALTER TABLE "AutomationRule" ADD CONSTRAINT automation_rule_name_present CHECK (length(btrim("name")) BETWEEN 1 AND 120);
ALTER TABLE "AutomationRule" ADD CONSTRAINT automation_rule_archived CHECK (("archivedAt" IS NULL) = ("archivedById" IS NULL));
CREATE TRIGGER automation_rule_immutable
  BEFORE UPDATE ON "AutomationRule"
  FOR EACH ROW EXECUTE FUNCTION leadro_immutable_columns('id', 'tenantId', 'key', 'createdById', 'createdAt');
CREATE TRIGGER automation_rule_no_delete BEFORE DELETE ON "AutomationRule" FOR EACH ROW EXECUTE FUNCTION leadro_no_delete();

-- ───────────── Automation rule versions ─────────────
ALTER TABLE "AutomationRuleVersion" ADD CONSTRAINT automation_rule_version_number CHECK ("version" >= 1);
ALTER TABLE "AutomationRuleVersion" ADD CONSTRAINT automation_rule_version_trigger_format CHECK (leadro_is_dotted_key("trigger"));
ALTER TABLE "AutomationRuleVersion" ADD CONSTRAINT automation_rule_version_priority_range CHECK ("priority" BETWEEN 0 AND 1000);
-- Conditions: 0-50 objects (declarative operators; no code). Actions: 1-20 objects, each naming its "type" (the action registry).
ALTER TABLE "AutomationRuleVersion" ADD CONSTRAINT automation_rule_version_conditions_shape
  CHECK (leadro_is_json_object_array("conditions", 0, 50) AND octet_length("conditions"::text) <= 32768);
ALTER TABLE "AutomationRuleVersion" ADD CONSTRAINT automation_rule_version_actions_shape
  CHECK (leadro_is_json_object_array("actions", 1, 20) AND octet_length("actions"::text) <= 32768
    AND NOT jsonb_path_exists("actions", 'lax $[*] ? (!(@."type".type() == "string"))'));
ALTER TABLE "AutomationRuleVersion" ADD CONSTRAINT automation_rule_version_no_secrets
  CHECK (NOT leadro_json_has_secret_key("conditions") AND NOT leadro_json_has_secret_key("actions"));
-- Status facts: a pending version has a request and a submission time; an active one an activation time and, when high-impact,
-- the approval request it was activated through (spec 15.2); a retired one its retirement time.
ALTER TABLE "AutomationRuleVersion" ADD CONSTRAINT automation_rule_version_pending
  CHECK ("status" <> 'PENDING_APPROVAL' OR ("approvalRequestId" IS NOT NULL AND "submittedAt" IS NOT NULL));
ALTER TABLE "AutomationRuleVersion" ADD CONSTRAINT automation_rule_version_active
  CHECK ("status" <> 'ACTIVE' OR ("activatedAt" IS NOT NULL AND (NOT "highImpact" OR "approvalRequestId" IS NOT NULL)));
ALTER TABLE "AutomationRuleVersion" ADD CONSTRAINT automation_rule_version_retired
  CHECK ("status" <> 'RETIRED' OR "retiredAt" IS NOT NULL);
-- At most one ACTIVE version per rule (activating N+1 retires N first, in the same transaction).
CREATE UNIQUE INDEX automation_rule_version_one_active
  ON "AutomationRuleVersion" ("tenantId", "ruleId") WHERE "status" = 'ACTIVE';
-- PENDING_APPROVAL -> DRAFT on rejection / cancellation / expiry (editable again; resubmitting opens a new request).
CREATE TRIGGER automation_rule_version_status
  BEFORE UPDATE ON "AutomationRuleVersion"
  FOR EACH ROW EXECUTE FUNCTION leadro_status_transitions(
    'DRAFT>PENDING_APPROVAL', 'PENDING_APPROVAL>DRAFT', 'PENDING_APPROVAL>ACTIVE', 'DRAFT>ACTIVE', 'ACTIVE>RETIRED', 'DRAFT>RETIRED');
CREATE TRIGGER automation_rule_version_immutable
  BEFORE UPDATE ON "AutomationRuleVersion"
  FOR EACH ROW EXECUTE FUNCTION leadro_immutable_columns('id', 'tenantId', 'ruleId', 'version', 'createdById', 'createdAt');
-- A version's content is editable only while it is a DRAFT: once submitted, active or retired it is what was approved and what
-- ran. A different trigger, condition, action, scope, priority or impact class is a new version.
CREATE OR REPLACE FUNCTION leadro_automation_rule_version_content_guard() RETURNS trigger
LANGUAGE plpgsql AS $$
BEGIN
  IF OLD."status" <> 'DRAFT' AND (
       NEW."trigger" IS DISTINCT FROM OLD."trigger" OR NEW."conditions" IS DISTINCT FROM OLD."conditions"
       OR NEW."actions" IS DISTINCT FROM OLD."actions" OR NEW."scopeOrgUnitId" IS DISTINCT FROM OLD."scopeOrgUnitId"
       OR NEW."priority" IS DISTINCT FROM OLD."priority" OR NEW."highImpact" IS DISTINCT FROM OLD."highImpact") THEN
    RAISE EXCEPTION 'a submitted automation rule version is frozen; create a new version instead'
      USING ERRCODE = 'restrict_violation';
  END IF;
  RETURN NEW;
END
$$;
CREATE TRIGGER automation_rule_version_content_guard
  BEFORE UPDATE ON "AutomationRuleVersion"
  FOR EACH ROW EXECUTE FUNCTION leadro_automation_rule_version_content_guard();
CREATE TRIGGER automation_rule_version_no_delete
  BEFORE DELETE ON "AutomationRuleVersion" FOR EACH ROW EXECUTE FUNCTION leadro_no_delete();

-- ───────────── Automation executions (append-only) ─────────────
ALTER TABLE "AutomationExecution" ADD CONSTRAINT automation_execution_entity
  CHECK ("entityType" ~ '^[A-Z][A-Za-z0-9]{0,62}$' AND length(btrim("entityId")) BETWEEN 1 AND 64);
ALTER TABLE "AutomationExecution" ADD CONSTRAINT automation_execution_actions_shape
  CHECK (leadro_is_json_object_array("actionsTaken", 0, 20) AND octet_length("actionsTaken"::text) <= 16384
    AND NOT leadro_json_has_secret_key("actionsTaken"));
ALTER TABLE "AutomationExecution" ADD CONSTRAINT automation_execution_depth CHECK ("causationDepth" BETWEEN 0 AND 16);
-- A failure says why; a run that executed nothing (not matched, suppressed) records no actions.
ALTER TABLE "AutomationExecution" ADD CONSTRAINT automation_execution_error
  CHECK (("errorCode" IS NULL OR leadro_is_code("errorCode"))
    AND ("result" <> 'FAILED' OR "errorCode" IS NOT NULL)
    AND ("result" <> 'EXECUTED' OR "errorCode" IS NULL));
ALTER TABLE "AutomationExecution" ADD CONSTRAINT automation_execution_no_actions_when_skipped
  CHECK ("result" NOT IN ('NOT_MATCHED', 'SUPPRESSED_DEPTH', 'SUPPRESSED_REPEAT') OR "actionsTaken" = '[]'::jsonb);
CREATE TRIGGER automation_execution_no_update_delete
  BEFORE UPDATE OR DELETE ON "AutomationExecution"
  FOR EACH ROW EXECUTE FUNCTION leadro_append_only();
CREATE TRIGGER automation_execution_no_truncate
  BEFORE TRUNCATE ON "AutomationExecution"
  FOR EACH STATEMENT EXECUTE FUNCTION leadro_append_only();

-- ───────────── Integrations ─────────────
ALTER TABLE "Integration" ADD CONSTRAINT integration_key_format CHECK (leadro_is_code("key"));
ALTER TABLE "Integration" ADD CONSTRAINT integration_provider_key_format CHECK ("providerKey" ~ '^[a-z][a-z0-9_-]{0,62}$');
ALTER TABLE "Integration" ADD CONSTRAINT integration_name_present CHECK (length(btrim("name")) BETWEEN 1 AND 120);
-- Non-secret configuration only (spec 18.1): objects, bounded, and no secret-looking key at any depth.
ALTER TABLE "Integration" ADD CONSTRAINT integration_config_no_secrets
  CHECK (leadro_is_small_json_object("config", 16384) AND NOT leadro_json_has_secret_key("config"));
ALTER TABLE "Integration" ADD CONSTRAINT integration_webhook_settings_no_secrets
  CHECK (leadro_is_small_json_object("webhookSettings", 16384) AND NOT leadro_json_has_secret_key("webhookSettings"));
-- A credentials REFERENCE, never a secret: "env:<VARIABLE_NAME>" or "vault:<path>" (the SecretStore resolves it).
ALTER TABLE "Integration" ADD CONSTRAINT integration_credentials_ref_format
  CHECK ("credentialsRef" IS NULL OR "credentialsRef" ~ '^(env:[A-Z][A-Z0-9_]{0,127}|vault:[A-Za-z0-9_][A-Za-z0-9_./-]{0,199})$');
-- Truthful status: CONNECTED only after a connection test; ERROR always says why; codes are stable.
ALTER TABLE "Integration" ADD CONSTRAINT integration_status_facts
  CHECK (("status" <> 'CONNECTED' OR "lastCheckedAt" IS NOT NULL)
    AND ("status" <> 'ERROR' OR "statusCode" IS NOT NULL)
    AND ("statusCode" IS NULL OR leadro_is_code("statusCode")));
-- Every inbound event is authenticated (spec 18.3): webhooks can be on only with a credentials reference for the signing secret.
ALTER TABLE "Integration" ADD CONSTRAINT integration_webhook_needs_credentials
  CHECK (NOT "webhookEnabled" OR "credentialsRef" IS NOT NULL);
ALTER TABLE "Integration" ADD CONSTRAINT integration_retry_policy
  CHECK ("retryMaxAttempts" BETWEEN 1 AND 25
    AND "retryBaseDelaySeconds" BETWEEN 1 AND 86400
    AND "retryMaxDelaySeconds" BETWEEN "retryBaseDelaySeconds" AND 86400);
CREATE TRIGGER integration_immutable
  BEFORE UPDATE ON "Integration"
  FOR EACH ROW EXECUTE FUNCTION leadro_immutable_columns('id', 'tenantId', 'key', 'category', 'providerKey', 'createdById', 'createdAt');
-- Disabled, never deleted (its logs and webhook events refer to it).
CREATE TRIGGER integration_no_delete BEFORE DELETE ON "Integration" FOR EACH ROW EXECUTE FUNCTION leadro_no_delete();

-- ───────────── Integration logs (append-only) ─────────────
ALTER TABLE "IntegrationLog" ADD CONSTRAINT integration_log_subject
  CHECK ("integrationId" IS NOT NULL OR "webhookEventId" IS NOT NULL);
ALTER TABLE "IntegrationLog" ADD CONSTRAINT integration_log_operation_format
  CHECK ("operation" ~ '^[a-z][a-z0-9_]{0,62}(\.[a-z][a-z0-9_]{0,62}){0,3}$');
ALTER TABLE "IntegrationLog" ADD CONSTRAINT integration_log_numbers
  CHECK (("httpStatus" IS NULL OR "httpStatus" BETWEEN 100 AND 599) AND "attempt" >= 1 AND ("durationMs" IS NULL OR "durationMs" >= 0));
ALTER TABLE "IntegrationLog" ADD CONSTRAINT integration_log_error
  CHECK (("errorCode" IS NULL OR leadro_is_code("errorCode")) AND ("outcome" <> 'FAILURE' OR "errorCode" IS NOT NULL));
ALTER TABLE "IntegrationLog" ADD CONSTRAINT integration_log_details_no_secrets
  CHECK (leadro_is_small_json_object("details", 4096) AND NOT leadro_json_has_secret_key("details"));
CREATE TRIGGER integration_log_no_update_delete
  BEFORE UPDATE OR DELETE ON "IntegrationLog"
  FOR EACH ROW EXECUTE FUNCTION leadro_append_only();
CREATE TRIGGER integration_log_no_truncate
  BEFORE TRUNCATE ON "IntegrationLog"
  FOR EACH STATEMENT EXECUTE FUNCTION leadro_append_only();

-- ───────────── Webhook events ─────────────
ALTER TABLE "WebhookEvent" ADD CONSTRAINT webhook_event_identity
  CHECK ("provider" ~ '^[a-z][a-z0-9_-]{0,62}$'
    AND length(btrim("externalId")) BETWEEN 1 AND 200
    AND length(btrim("eventType")) BETWEEN 1 AND 100);
ALTER TABLE "WebhookEvent" ADD CONSTRAINT webhook_event_hash_format CHECK ("payloadHash" ~ '^[0-9a-f]{64}$');
-- A forged event is never validated or handled, and is stored under its body hash, not under the id it claims (so it can never
-- pre-claim a genuine event id and turn the real delivery into a "duplicate").
ALTER TABLE "WebhookEvent" ADD CONSTRAINT webhook_event_signature_gate
  CHECK ("signatureResult" = 'VALID'
    OR ("validationResult" = 'SKIPPED' AND "handlingStatus" = 'REJECTED' AND "externalId" = 'unverified:' || "payloadHash"));
ALTER TABLE "WebhookEvent" ADD CONSTRAINT webhook_event_validated_when_signed
  CHECK ("signatureResult" = 'INVALID' OR "validationResult" <> 'SKIPPED');
-- Nothing invalid is ever handled (spec 18.3 "validated before modifying core records").
ALTER TABLE "WebhookEvent" ADD CONSTRAINT webhook_event_validation_gate
  CHECK ("validationResult" = 'VALID' OR "handlingStatus" = 'REJECTED');
ALTER TABLE "WebhookEvent" ADD CONSTRAINT webhook_event_rejection_code
  CHECK (("handlingStatus" = 'REJECTED') = ("rejectionCode" IS NOT NULL)
    AND ("rejectionCode" IS NULL OR leadro_is_code("rejectionCode")));
ALTER TABLE "WebhookEvent" ADD CONSTRAINT webhook_event_parsed
  CHECK (("parsed" IS NULL OR (leadro_is_small_json_object("parsed", 16384) AND NOT leadro_json_has_secret_key("parsed")))
    AND ("handlingStatus" <> 'REJECTED' OR "parsed" IS NULL));
ALTER TABLE "WebhookEvent" ADD CONSTRAINT webhook_event_handling
  CHECK (("handlingCode" IS NULL OR leadro_is_code("handlingCode"))
    AND ("handlingStatus" <> 'HANDLED' OR ("handlingCode" IS NOT NULL AND "handledAt" IS NOT NULL))
    AND ("handlingStatus" <> 'FAILED' OR "handlingCode" IS NOT NULL));
-- REJECTED is final from the start (inserted as such). FAILED -> RECEIVED is an admin replay of a dead handler job.
CREATE OR REPLACE FUNCTION leadro_webhook_event_handling_transitions() RETURNS trigger
LANGUAGE plpgsql AS $$
BEGIN
  -- leadro_status_transitions reads a column named "status"; WebhookEvent names it "handlingStatus".
  IF OLD."handlingStatus" IS DISTINCT FROM NEW."handlingStatus"
     AND NOT ((OLD."handlingStatus"::text || '>' || NEW."handlingStatus"::text) = ANY (TG_ARGV)) THEN
    RAISE EXCEPTION 'WebhookEvent handlingStatus transition % -> % is not allowed', OLD."handlingStatus", NEW."handlingStatus"
      USING ERRCODE = 'restrict_violation';
  END IF;
  RETURN NEW;
END
$$;
CREATE TRIGGER webhook_event_status
  BEFORE UPDATE ON "WebhookEvent"
  FOR EACH ROW EXECUTE FUNCTION leadro_webhook_event_handling_transitions(
    'RECEIVED>HANDLED', 'RECEIVED>FAILED', 'FAILED>RECEIVED');
-- The record of what arrived and how it was judged never changes; only the handling outcome is written later.
CREATE TRIGGER webhook_event_immutable
  BEFORE UPDATE ON "WebhookEvent"
  FOR EACH ROW EXECUTE FUNCTION leadro_immutable_columns(
    'id', 'tenantId', 'integrationId', 'provider', 'externalId', 'eventType', 'payloadHash', 'signatureResult', 'validationResult',
    'rejectionCode', 'parsed', 'receivedAt');
CREATE TRIGGER webhook_event_no_delete BEFORE DELETE ON "WebhookEvent" FOR EACH ROW EXECUTE FUNCTION leadro_no_delete();

-- ───────────── Phase 4 payment intake: link to the generic event ─────────────
-- Re-created with "webhookEventId" added to the frozen columns (the Phase 4 list is otherwise unchanged).
DROP TRIGGER payment_intake_event_immutable ON "PaymentIntakeEvent";
CREATE TRIGGER payment_intake_event_immutable
  BEFORE UPDATE ON "PaymentIntakeEvent"
  FOR EACH ROW EXECUTE FUNCTION leadro_immutable_columns(
    'tenantId', 'provider', 'externalId', 'eventType', 'payloadHash', 'signatureValid', 'receivedAt', 'webhookEventId');

-- ───────────── Accounting mappings ─────────────
ALTER TABLE "AccountingMapping" ADD CONSTRAINT accounting_mapping_version_number CHECK ("version" >= 1);
ALTER TABLE "AccountingMapping" ADD CONSTRAINT accounting_mapping_mappings_shape
  CHECK (leadro_is_json_object_array("mappings", 1, 500) AND octet_length("mappings"::text) <= 262144
    AND NOT leadro_json_has_secret_key("mappings"));
-- The mapping always goes through an approval request (no "no policy = apply directly" path): accounting treatment must be
-- reviewed (spec 11.x).
ALTER TABLE "AccountingMapping" ADD CONSTRAINT accounting_mapping_needs_approval
  CHECK ("status" NOT IN ('PENDING_APPROVAL', 'ACTIVE') OR "approvalRequestId" IS NOT NULL);
ALTER TABLE "AccountingMapping" ADD CONSTRAINT accounting_mapping_status_times
  CHECK (("status" <> 'PENDING_APPROVAL' OR "submittedAt" IS NOT NULL)
    AND ("status" <> 'ACTIVE' OR "activatedAt" IS NOT NULL)
    AND ("status" <> 'RETIRED' OR "retiredAt" IS NOT NULL));
-- Versions per legal entity (NULL = the tenant default series), and at most one ACTIVE per series. (The first index is partial
-- with an always-true predicate only so that `prisma migrate diff` leaves it alone.)
CREATE UNIQUE INDEX accounting_mapping_version_unique
  ON "AccountingMapping" ("tenantId", "legalEntityId", "version") NULLS NOT DISTINCT WHERE "version" IS NOT NULL;
CREATE UNIQUE INDEX accounting_mapping_one_active
  ON "AccountingMapping" ("tenantId", "legalEntityId") NULLS NOT DISTINCT WHERE "status" = 'ACTIVE';
CREATE TRIGGER accounting_mapping_status
  BEFORE UPDATE ON "AccountingMapping"
  FOR EACH ROW EXECUTE FUNCTION leadro_status_transitions(
    'DRAFT>PENDING_APPROVAL', 'PENDING_APPROVAL>DRAFT', 'PENDING_APPROVAL>ACTIVE', 'ACTIVE>RETIRED', 'DRAFT>RETIRED');
CREATE TRIGGER accounting_mapping_immutable
  BEFORE UPDATE ON "AccountingMapping"
  FOR EACH ROW EXECUTE FUNCTION leadro_immutable_columns('id', 'tenantId', 'legalEntityId', 'version', 'createdById', 'createdAt');
CREATE OR REPLACE FUNCTION leadro_accounting_mapping_content_guard() RETURNS trigger
LANGUAGE plpgsql AS $$
BEGIN
  IF OLD."status" <> 'DRAFT' AND NEW."mappings" IS DISTINCT FROM OLD."mappings" THEN
    RAISE EXCEPTION 'a submitted accounting mapping version is frozen; create a new version instead'
      USING ERRCODE = 'restrict_violation';
  END IF;
  RETURN NEW;
END
$$;
CREATE TRIGGER accounting_mapping_content_guard
  BEFORE UPDATE ON "AccountingMapping"
  FOR EACH ROW EXECUTE FUNCTION leadro_accounting_mapping_content_guard();
CREATE TRIGGER accounting_mapping_no_delete BEFORE DELETE ON "AccountingMapping" FOR EACH ROW EXECUTE FUNCTION leadro_no_delete();

-- ───────────── Export batches ─────────────
ALTER TABLE "ExportBatch" ADD CONSTRAINT export_batch_period
  CHECK ("periodEnd" > "periodStart" AND "periodEnd" - "periodStart" <= 366);
ALTER TABLE "ExportBatch" ADD CONSTRAINT export_batch_content
  CHECK ("contentHash" ~ '^[0-9a-f]{64}$' AND "rowCount" >= 0 AND length("idempotencyKey") BETWEEN 1 AND 200);
-- Payroll exports carry time facts only: no mapping, no money totals (spec 11.9). Accounting exports name the approved mapping
-- version used and carry their per-currency totals.
ALTER TABLE "ExportBatch" ADD CONSTRAINT export_batch_kind_shape
  CHECK (CASE "kind"
    WHEN 'PAYROLL' THEN "accountingMappingId" IS NULL AND "totals" IS NULL
    ELSE "accountingMappingId" IS NOT NULL AND leadro_is_small_json_object("totals", 16384)
  END);
-- A payroll batch is released only through an approval request; any pending batch has one.
ALTER TABLE "ExportBatch" ADD CONSTRAINT export_batch_needs_approval
  CHECK (("status" <> 'PENDING_APPROVAL' OR "approvalRequestId" IS NOT NULL)
    AND ("kind" <> 'PAYROLL' OR "status" NOT IN ('APPROVED', 'EXPORTED') OR "approvalRequestId" IS NOT NULL));
ALTER TABLE "ExportBatch" ADD CONSTRAINT export_batch_exported CHECK ("status" <> 'EXPORTED' OR "exportedAt" IS NOT NULL);
ALTER TABLE "ExportBatch" ADD CONSTRAINT export_batch_failure_code
  CHECK (("status" = 'FAILED') = ("failureCode" IS NOT NULL) AND ("failureCode" IS NULL OR leadro_is_code("failureCode")));
ALTER TABLE "ExportBatch" ADD CONSTRAINT export_batch_not_own_supersede CHECK ("supersedesBatchId" IS DISTINCT FROM "id");
-- Rejected / cancelled batches are CANCELLED (the content is fixed; preparing again makes a new batch). Re-exporting an EXPORTED
-- batch reproduces the same file (same contentHash) and changes nothing here. FAILED -> APPROVED is a retry.
CREATE TRIGGER export_batch_status
  BEFORE UPDATE ON "ExportBatch"
  FOR EACH ROW EXECUTE FUNCTION leadro_status_transitions(
    'PREPARED>PENDING_APPROVAL', 'PREPARED>APPROVED', 'PREPARED>CANCELLED', 'PENDING_APPROVAL>APPROVED',
    'PENDING_APPROVAL>CANCELLED', 'APPROVED>EXPORTED', 'APPROVED>FAILED', 'APPROVED>CANCELLED', 'FAILED>APPROVED');
CREATE TRIGGER export_batch_immutable
  BEFORE UPDATE ON "ExportBatch"
  FOR EACH ROW EXECUTE FUNCTION leadro_immutable_columns(
    'id', 'tenantId', 'kind', 'legalEntityId', 'periodStart', 'periodEnd', 'format', 'accountingMappingId', 'contentHash', 'rowCount',
    'totals', 'idempotencyKey', 'supersedesBatchId', 'preparedById', 'createdAt');
-- An accounting batch is prepared from the ACTIVE mapping of its own series (same legal entity, or the tenant default).
CREATE OR REPLACE FUNCTION leadro_export_batch_mapping_guard() RETURNS trigger
LANGUAGE plpgsql AS $$
DECLARE
  m "AccountingMapping"%ROWTYPE;
BEGIN
  IF NEW."accountingMappingId" IS NULL THEN
    RETURN NEW;
  END IF;
  SELECT * INTO m FROM "AccountingMapping" WHERE "id" = NEW."accountingMappingId" AND "tenantId" = NEW."tenantId";
  IF NOT FOUND THEN
    RAISE EXCEPTION 'accounting mapping % does not exist', NEW."accountingMappingId" USING ERRCODE = 'foreign_key_violation';
  END IF;
  IF m."status" <> 'ACTIVE' THEN
    RAISE EXCEPTION 'an accounting export needs an ACTIVE (approved) mapping; mapping % is %', m."id", m."status"
      USING ERRCODE = 'restrict_violation';
  END IF;
  IF m."legalEntityId" IS NOT NULL AND m."legalEntityId" IS DISTINCT FROM NEW."legalEntityId" THEN
    RAISE EXCEPTION 'accounting mapping % belongs to another legal entity', m."id" USING ERRCODE = 'restrict_violation';
  END IF;
  RETURN NEW;
END
$$;
CREATE TRIGGER export_batch_mapping_guard
  BEFORE INSERT ON "ExportBatch" FOR EACH ROW EXECUTE FUNCTION leadro_export_batch_mapping_guard();
CREATE TRIGGER export_batch_no_delete BEFORE DELETE ON "ExportBatch" FOR EACH ROW EXECUTE FUNCTION leadro_no_delete();
